#!/usr/bin/env python3
# Generated by Claude (AI-assisted).
"""Pack the Lean library the exercise editor loads into a few gzip files.

The editor needs about 7,000 small files (the `.olean`, `.ir` and `.ir.sig`
files of Init, Std and Lean, about 430 MB).  Served one by one they cost
thousands of requests and arrive uncompressed, since Cloudflare does not
compress binary types.  Here they are concatenated, in path order, into packs
of about 40 MB, each gzipped (compressed well under Pages' 25 MB file limit),
and indexed in `library-packs.json`:

    {"packs": [{"file": "library/pack-000.bin", "bytes": <unpacked size>,
                "compressedBytes": <size of the file>,
                "entries": [[<path in lean-lib/>, <offset>, <length>], ...]}]}

`lean-worker.js` fetches the packs, inflates them with the browser's own
`DecompressionStream`, and writes each entry to Lean's virtual file system.

Usage: python3 pack_library.py <runtime dir> <out dir>
where <runtime dir> holds lean-lib-files.json and lean-lib/ (as for build.sh),
and <out dir> receives library-packs.json and library/pack-NNN.bin.
"""

import gzip
import json
import os
import sys

# The layers the exercises import from; lean-worker.js loads the same ones.
LAYERS = {"Init", "Std", "Lean"}
PACK_BYTES = 40 * 1024 * 1024


def library_files(runtime):
    files = []
    for path in json.load(open(os.path.join(runtime, "lean-lib-files.json"))):
        if not path.endswith(".olean") or path.split("/")[0].removesuffix(".olean") not in LAYERS:
            continue
        for p in (path, path[:-6] + ".ir", path[:-6] + ".ir.sig"):
            if os.path.exists(os.path.join(runtime, "lean-lib", p)):
                files.append(p)
    return sorted(files)


def main():
    runtime, out = sys.argv[1:3]
    os.makedirs(os.path.join(out, "library"), exist_ok=True)
    packs, chunk, entries = [], bytearray(), []

    def flush():
        if not entries:
            return
        name = f"library/pack-{len(packs):03d}.bin"
        # mtime=0 so the same library always packs to the same bytes.
        data = gzip.compress(bytes(chunk), compresslevel=9, mtime=0)
        with open(os.path.join(out, name), "wb") as f:
            f.write(data)
        packs.append({"file": name, "bytes": len(chunk), "compressedBytes": len(data),
                      "entries": list(entries)})
        chunk.clear()
        entries.clear()

    for path in library_files(runtime):
        with open(os.path.join(runtime, "lean-lib", path), "rb") as f:
            data = f.read()
        if chunk and len(chunk) + len(data) > PACK_BYTES:
            flush()
        entries.append([path, len(chunk), len(data)])
        chunk.extend(data)
    flush()

    with open(os.path.join(out, "library-packs.json"), "w") as f:
        json.dump({"packs": packs}, f, separators=(",", ":"))
    raw = sum(p["bytes"] for p in packs)
    packed = sum(p["compressedBytes"] for p in packs)
    print(f"{sum(len(p['entries']) for p in packs)} files in {len(packs)} packs: "
          f"{raw / 1e6:.0f} MB -> {packed / 1e6:.0f} MB, largest pack "
          f"{max(p['compressedBytes'] for p in packs) / 1e6:.1f} MB")


if __name__ == "__main__":
    main()
